/** Fresh owned GLB bytes. Pass a course to adapt scenery to its flight bounds;
 * pass an environment ID for the standard 76 × 70 m built-in world. */
export function builtinWorldScene(course) {
  const environment = typeof course === 'string' ? course : course?.environment;
  if (
    !['woodland', 'courtyard', 'warehouse', 'stadium', 'container-yard', 'garage'].includes(
      environment,
    )
  )
    return null;
  const bounds =
    typeof course === 'object' && course.bounds
      ? course.bounds
      : { min: { x: -38000, y: 0, z: -38000 }, max: { x: 38000, y: 18000, z: 32000 } };
  const minX = bounds.min.x / 1000,
    maxX = bounds.max.x / 1000;
  const minZ = bounds.min.z / 1000,
    maxZ = bounds.max.z / 1000;
  const { json: original, bin: originalBin, models } = readLibrary();
  const json = structuredClone(original);
  const roots = [],
    placements = [];
  const cloneNode = (index) => {
    const node = structuredClone(original.nodes[index]);
    if (node.children) node.children = node.children.map(cloneNode);
    const next = json.nodes.length;
    json.nodes.push(node);
    return next;
  };
  function edge(name, side, along, height, gap = 1, offsetY = 0) {
    const model = models.get(name);
    if (!model) throw new Error(`Missing built-in scenery: ${name}`);
    const scale = height / model.size[1];
    const yaw = [0, -Math.PI / 2, Math.PI, Math.PI / 2][side];
    const halfX = ((side % 2 ? model.size[2] : model.size[0]) * scale) / 2;
    const halfZ = ((side % 2 ? model.size[0] : model.size[2]) * scale) / 2;
    const x =
      side === 1
        ? maxX + gap + halfX
        : side === 3
          ? minX - gap - halfX
          : minX + (maxX - minX) * along;
    const z =
      side === 0
        ? minZ - gap - halfZ
        : side === 2
          ? maxZ + gap + halfZ
          : minZ + (maxZ - minZ) * along;
    if (!(x + halfX < minX || x - halfX > maxX || z + halfZ < minZ || z - halfZ > maxZ))
      throw new Error('Scenery overlaps flight bounds');
    const index = json.nodes.length;
    json.nodes.push({
      name: `scenery-${placements.length + 1}`,
      translation: [x, bounds.min.y / 1000 + offsetY, z],
      rotation: [0, Math.sin(yaw / 2), 0, Math.cos(yaw / 2)],
      scale: [scale, scale, scale],
      children: [],
    });
    json.nodes[index].children.push(cloneNode(model.index));
    roots.push(index);
    placements.push({
      model: name,
      side,
      bounds: {
        min: [x - halfX, bounds.min.y / 1000 + offsetY, z - halfZ],
        max: [x + halfX, bounds.min.y / 1000 + offsetY + height, z + halfZ],
      },
    });
  }
  const retro = (name, ...args) => edge(`retro-urban/${name}`, ...args);
  const industrial = (name, ...args) => edge(`city-industrial/${name}`, ...args);
  if (environment === 'woodland' || environment === 'courtyard') {
    for (let side = 0; side < 4; side++) {
      const count = environment === 'woodland' ? 10 : 3;
      for (let i = 0; i < count; i++) {
        // Alternating clusters, setbacks and canopy heights give each edge a
        // recognizable silhouette without filling any authored flight opening.
        const along = Math.min(
          0.96,
          Math.max(0.04, (i + 0.5 + Math.sin(i * 2.7 + side) * 0.22) / count),
        );
        retro(
          (i + side) % 3 === 0 ? 'tree-park-pine-large' : 'tree-park-large',
          side,
          along,
          environment === 'woodland' ? 5.5 + ((i * 3 + side) % 5) * 1.2 : 5.2 + (i % 2),
          environment === 'woodland' ? 1.5 + ((i + side) % 3) * 2 : 3.5,
        );
        if (i % 4 === 1) retro('detail-bench', side, along, 1.1, 1.2);
      }
    }
  }
  if (environment === 'courtyard' || environment === 'stadium') {
    // The existing three-bay height groups become connected courtyard terraces.
    // Fixed metre-scale bay spacing avoids isolated blocks in larger lessons;
    // uneven alleys and setbacks give each street front a distinct silhouette.
    // The stadium keeps its original single pavilion and exact placement.
    const sides = environment === 'stadium' ? [0] : [0, 1, 2, 3];
    const terraceCentres = [
      [0.1, 0.3, 0.64, 0.86],
      [0.12, 0.4, 0.66, 0.88],
      [0.14, 0.36, 0.67, 0.87],
      [0.1, 0.33, 0.61, 0.85],
    ];
    const setbacks = [8, 10, 12, 9];
    for (const side of sides) {
      const span = side % 2 ? maxZ - minZ : maxX - minX;
      // All authored courtyards span at least 70 m. Retain the old layout for
      // small creator worlds instead of squeezing full-size terrace groups.
      const terraces = environment === 'courtyard' && span >= 64;
      for (let i = 0; i < 12; i++) {
        const group = Math.floor(i / 3),
          along = terraces
            ? terraceCentres[side][group] + (((i % 3) - 1) * 4.04) / span
            : (i + 0.5) / 12,
          gap = terraces ? setbacks[(group + side) % 4] : environment === 'stadium' ? 18 : 8;
        const floors = environment === 'stadium' || (group + side) % 3 === 1 ? 2 : 1;
        retro(
          i % 4 === 1 ? 'wall-a-door' : i % 4 === 2 ? 'wall-a-garage' : 'wall-a-window',
          side,
          along,
          4,
          gap,
        );
        if (floors === 2) retro('wall-a-window', side, along, 4, gap, 4);
        retro('wall-a-roof', side, along, 2, gap, floors * 4);
      }
      retro('detail-light-double', side, 0.18, 6, 1.5);
      retro('detail-light-double', side, 0.82, 6, 1.5);
      if (environment === 'courtyard') retro('detail-dumpster-closed', side, 0.06, 1.4, 2);
    }
  }
  if (['warehouse', 'container-yard', 'garage'].includes(environment)) {
    // Distinct industrial settings, not the same mirrored row on every side.
    const yard = environment === 'container-yard';
    const garage = environment === 'garage';
    for (let side = 0; side < 4; side++) {
      if (yard || side % 2 === 0) {
        const buildings = garage
          ? ['building-d', 'building-l']
          : ['building-a', 'building-d', 'building-l'];
        buildings.forEach((name, i) =>
          industrial(
            name,
            side,
            (i + 0.5) / buildings.length,
            (garage ? 14 : 10) + i * 2 + side,
            garage ? 24 : 14,
          ),
        );
      }
      if (!garage && (yard || side === 1)) {
        for (let i = 0; i < (yard ? 4 : 2); i++) {
          const along = 0.16 + i * 0.17;
          const name = (side + i) % 2 ? 'shipping-container-a' : 'shipping-container-b';
          industrial(name, side, along, 2.8, 1.5 + (i % 2) * 0.4);
          if (yard && (i + side) % 3 !== 0)
            industrial(name, side, along, 2.8, 1.5 + (i % 2) * 0.4, 2.8);
        }
      }
      if (side === 3 || (yard && side === 1)) {
        retro('truck-green', side, 0.72, 3.1, 2);
        retro('truck-green-cargo', side, 0.84, 2.7, 2.5);
      }
      if (!garage && side % 2 === 0) {
        for (let i = 0; i < 3; i++) {
          retro('pallet', side, 0.78 + i * 0.05, 0.6, 1);
          if (i !== 1) retro('pallet', side, 0.78 + i * 0.05, 0.6, 1, 0.6);
        }
      }
      retro('detail-light-double', side, side % 2 ? 0.08 : 0.9, 6, 1.5);
    }
    if (yard) {
      industrial('water-tower', 0, 0.94, 24, 5);
      industrial('detail-tank', 2, 0.03, 4.5, 6);
    } else if (!garage) industrial('detail-tank', 0, 0.04, 6, 8);
  }
  if (environment === 'warehouse') {
    for (let side = 0; side < 4; side++)
      for (let i = 0; i < 8; i++) retro('wall-a-flat-window', side, (i + 0.5) / 8, 6, 0.5, 2.5);
  }
  json.scenes = [{ name: `${environment} · Kenney CC0 scenery`, nodes: roots }];
  json.scene = 0;
  json.asset.extras = {
    ...(json.asset.extras ?? {}),
    author: 'Kenney',
    license: 'CC0-1.0',
    fpvScenery: true,
    environment,
    placements,
  };
  const bin = instanceScenery(json, roots, placements, originalBin);
  const pixels =
    environment === 'warehouse' || environment === 'stadium' || course?.world?.theme === 'pixel';
  // glTF defaults omitted metallicFactor to 1. These closed-library park
  // surfaces are dielectric; the original textures describe colour, not metal.
  // Scope to the natural Woodland presentation, never arbitrary creator imports.
  if (
    environment === 'woodland' &&
    !pixels &&
    course?.theme !== 'pixel' &&
    course?.themeProfile?.textureFilter !== 'nearest'
  ) {
    const surfaces = {
      treeA: [0, 1],
      treeB: [0, 1],
      dirt: [0, 1],
      planks: [0, 0.92],
      concreteSmooth: [0, 0.86],
      concrete: [0, 0.94],
      metal: [0.35, 0.64],
      wall_metal: [0.08, 0.76],
    };
    for (const material of json.materials ?? []) {
      const surface = surfaces[material.name];
      if (!surface) continue;
      // This library was authored unlit. Natural scenery should receive the
      // world's lighting; explicit metalness avoids glTF's metallic default.
      if (material.extensions) delete material.extensions.KHR_materials_unlit;
      material.pbrMetallicRoughness = {
        ...material.pbrMetallicRoughness,
        metallicFactor: surface[0],
        roughnessFactor: surface[1],
      };
    }
  }
  if (pixels)
    for (const sampler of json.samplers ?? []) {
      sampler.magFilter = 9728;
      sampler.minFilter = 9984;
    }
  const text = new TextEncoder().encode(JSON.stringify(json));
  const length = (text.byteLength + 3) & ~3;
  const header = new Uint8Array(20 + length + 8);
  const view = new DataView(header.buffer);
  view.setUint32(0, 0x46546c67, true);
  view.setUint32(4, 2, true);
  view.setUint32(8, header.byteLength + bin.byteLength, true);
  view.setUint32(12, length, true);
  view.setUint32(16, 0x4e4f534a, true);
  header.fill(32, 20, 20 + length);
  header.set(text, 20);
  view.setUint32(20 + length, bin.byteLength, true);
  view.setUint32(24 + length, 0x004e4942, true);
  return new Blob([header, bin], { type: 'model/gltf-binary' });
}
